def canPartition(nums):
    total_sum = sum(nums)
    # If total sum is odd, it's not possible to partition into two equal subsets
    if total_sum % 2 != 0:
        return False

    target = total_sum // 2
    n = len(nums)

    dp = [False] * (target + 1)
    dp[0] = True

    for num in nums:
        for i in range(target, num - 1, -1):
            dp[i] = dp[i] or dp[i - num]

    return dp[target]

