def max_expression(arr, k):
    """
    Finds the maximum value of max(arr[i], arr[j]) + k * |i - j| for different choices of subarrays (arr[i], arr[j]).
    """
    if not arr:
        return 0

    n = len(arr)
    max_value = float('-inf')

    for i in range(n):
        for j in range(i, n):
            current_value = max(arr[i], arr[j]) + k * (j - i)
            max_value = max(max_value, current_value)

    return max_value

