def is_rectangle(t, test_cases):
    """
    For each test case, determine if the connected component of 'X's forms a rectangle.
    """
    results = []

    for i in range(t):
        n, m = test_cases[i][0]
        grid = test_cases[i][1]

        # Identifying bounds of 'X' connected component
        top, bottom, left, right = n, 0, m, 0
        for row in range(n):
            for col in range(m):
                if grid[row][col] == 'X':
                    top = min(top, row)
                    bottom = max(bottom, row)
                    left = min(left, col)
                    right = max(right, col)

        # Checking if all cells within the bounds are 'X'
        is_rectangular = True
        for row in range(top, bottom + 1):
            for col in range(left, right + 1):
                if grid[row][col] != 'X':
                    is_rectangular = False
                    break
            if not is_rectangular:
                break

        if is_rectangular:
            results.append("YES")
        else:
            results.append("NO")

    return results

