def maxSumNonAdjacent(nums):
    """
    Returns the maximum sum of non-adjacent elements in the array.
    """
    if not nums:
        return 0
    if len(nums) == 1:
        return nums[0]

    include = 0
    exclude = 0

    for num in nums:
        new_exclude = max(include, exclude)
        include = exclude + num
        exclude = new_exclude

    return max(include, exclude)

