def count_pairs_with_sum(nums, target):
    """
    Returns the number of unique pairs (i, j) where i < j and nums[i] + nums[j] equals the target.
    """
    count = 0
    seen = set()

    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] + nums[j] == target and (i, j) not in seen:
                count += 1
                seen.add((i, j))

    return count

