def count_unique_pairs(arr, k):
    """
    Returns the number of unique pairs (i, j) where 0 <= i < j < len(arr) and arr[i] + arr[j] == k.
    """
    seen = set()
    unique_pairs = set()

    for i in range(len(arr)):
        complement = k - arr[i]
        if complement in seen:
            pair = tuple(sorted((arr[i], complement)))
            unique_pairs.add(pair)
        seen.add(arr[i])

    return len(unique_pairs)

from typing import List

def house_robber(houses: List[int]) -> int:
    if not houses:
        return 0

    n = len(houses)
    if n == 1:
        return houses[0]

    prev1, prev2 = 0, 0

    for money in houses:
        current = max(prev1, prev2 + money)
        prev2 = prev1
        prev1 = current

    return prev1

def longest_common_prefix(paths: list[str]) -> str:
    if not paths:
        return ""

    # Find the shortest path in the list (as the longest common prefix can't be longer than the shortest path)
    shortest_path = min(paths, key=len)

    # Iterate over the characters of the shortest path
    for i in range(len(shortest_path)):
        char = shortest_path[i]
        # Compare this character with the same position in all other paths
        for path in paths:
            if path[i] != char:
                # Return the substring of the shortest path if a mismatch is found
                return shortest_path[:i].rsplit('/', 1)[0] + '/'

    # If no mismatch was found, the entire shortest_path is the common prefix
    return shortest_path

