def modify_string_to_have_k_consecutive_chars(s, k):
    """
    Modify the string such that every character in the resulting string appears at least k times consecutively.
    If it's not possible to achieve this, return an empty string.
    """
    if not s:
        return "" if k > 0 else s

    from collections import Counter
    counts = Counter(s)

    for char_count in counts.values():
        if (char_count % k) != 0:
            return ""

    result = []
    for char, count in counts.items():
        result.append(char * count)

    return ''.join(result)

