def find_longest_equal_0s_1s_subarray(arr):
    """
    Finds the longest contiguous subarray with equal number of 0's and 1's.

    Args:
    arr: list of integers (0's and 1's)

    Returns:
    tuple: (start index, end index) of the longest subarray with equal 0's and 1's, or (-1, -1) if none found.
    """
    n = len(arr)
    position = {}
    sum = 0
    max_len = 0
    start_index = -1

    for i in range(n):
        sum += -1 if arr[i] == 0 else 1

        if sum == 0:
            max_len = i + 1
            start_index = 0

        if sum in position:
            # If sum is already seen, find the length of this subarray
            if max_len < (i - position[sum]):
                max_len = i - position[sum]
                start_index = position[sum] + 1
        else:
            position[sum] = i

    if max_len == 0:
        return (-1, -1)

    return (start_index, start_index + max_len - 1)

