def min_operations_to_non_decreasing(n, sequence):
    """
    Returns the minimum number of operations required to make the sequence non-decreasing.
    """
    operations = 0
    for i in range(1, n):
        if sequence[i] < sequence[i - 1]:
            operations += sequence[i - 1] - sequence[i]
            sequence[i] = sequence[i - 1]
    return operations

