def join_with_slash(base: str, suffix: str) -> str:
    """
    Combines a base path or URL with a suffix, ensuring no redundant slashes exist.
    """
    base = base.rstrip('/')
    suffix = suffix.strip('/')

    if base and suffix:
        return f"{base}/{suffix}"
    elif base:
        return base
    else:
        return suffix

