def find_out_of_order_position(n, sequence):
    """
    Finds the position of the out-of-order element in the sequence.

    :param n: An integer representing the number of elements in the sequence.
    :param sequence: A list of integers representing the sequence.
    :return: An integer representing the 1-based position of the out-of-order element.
    """
    for i in range(1, n):
        if sequence[i] < sequence[i - 1]:
            return i + 1
    return -1  # Edge case handling (although the problem guarantees one out-of-order element)

