def findSubstring(s, words):
    """
    Returns all the start indices of substring(s) that are concatenations of each word in words exactly once.
    """
    if not s or not words:
        return []

    word_length = len(words[0])
    word_count = len(words)
    substring_length = word_length * word_count

    # Build a word frequency dictionary
    word_frequency = {}
    for word in words:
        if word in word_frequency:
            word_frequency[word] += 1
        else:
            word_frequency[word] = 1

    result_indices = []

    for i in range(word_length):
        left = i
        right = i
        curr_frequency = {}
        word_used = 0

        while right + word_length <= len(s):
            # Extract word from right pointer
            word = s[right:right+word_length]
            right += word_length
            if word in word_frequency:
                if word in curr_frequency:
                    curr_frequency[word] += 1
                else:
                    curr_frequency[word] = 1

                word_used += 1

                # If there are more than needed of any word, shift the left pointer to the right to balance
                while curr_frequency[word] > word_frequency[word]:
                    left_word = s[left:left+word_length]
                    left += word_length
                    curr_frequency[left_word] -= 1
                    word_used -= 1

                # If all words are used the correct number of times, record the start index
                if word_used == word_count:
                    result_indices.append(left)
            else:
                # Reset the count and move on
                curr_frequency.clear()
                word_used = 0
                left = right

    return result_indices

