from collections import deque

def min_steps_to_reach_end(terrain, step_limit):
    n = len(terrain)
    if n == 1:
        return 0

    queue = deque([(0, 0)])  # (current index, steps taken)
    visited = {0}

    while queue:
        index, steps = queue.popleft()

        for neighbor in (index - 1, index + 1):
            if 0 <= neighbor < n and neighbor not in visited:
                if abs(terrain[neighbor] - terrain[index]) <= step_limit:
                    if neighbor == n - 1:
                        return steps + 1
                    queue.append((neighbor, steps + 1))
                    visited.add(neighbor)

    return -1

