import math

def find_gcd_of_range(n, m):
    """
    Returns the GCD of all numbers in the range [n, m].
    """
    if n == m:
        return n

    # If the difference between m and n is greater than 1
    # there is at least one pair of coprime numbers in the range
    # Thus, GCD will be 1
    if m - n > 1:
        return 1

    return math.gcd(n, m)

