from typing import List

def enhanced_interpolation_search(array: List[float], search_key: float) -> int:
    """
    Perform an interpolation search on a sorted array where the elements are in ascending order.
    Returns the index of search_key if found, else returns -1.
    """
    if not array:
        return -1

    low = 0
    high = len(array) - 1

    while low <= high and array[low] <= search_key <= array[high]:
        # If all elements are the same and match the search_key
        if array[high] == array[low]:
            if array[low] == search_key:
                return low
            else:
                return -1

        # Interpolation formula to estimate the position
        pos = low + int((search_key - array[low]) * (high - low) / (array[high] - array[low]))

        # Check if the estimated position is within the array bounds
        if pos < 0 or pos >= len(array):
            return -1

        # Check if the current position is the target
        if array[pos] == search_key:
            return pos

        # If search_key is larger, search in the upper part of the array
        if array[pos] < search_key:
            low = pos + 1
        # If search_key is smaller, search in the lower part of the array
        else:
            high = pos - 1

    return -1

