def longest_increasing_subsequence(purchases: list[int]) -> list[int]:
    if not purchases:
        return []

    n = len(purchases)
    dp = [1] * n
    prev_index = [-1] * n

    # Loop to fill dp array
    for i in range(1, n):
        for j in range(i):
            if purchases[i] > purchases[j] and dp[i] < dp[j] + 1:
                dp[i] = dp[j] + 1
                prev_index[i] = j

    # Find the index of the maximum value in dp
    max_index = 0
    for i in range(1, n):
        if dp[i] > dp[max_index]:
            max_index = i

    # Reconstruct the longest increasing subsequence
    lis = []
    k = max_index
    while k != -1:
        lis.append(purchases[k])
        k = prev_index[k]

    lis.reverse()
    return lis

